package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

// ==================================================
// Phase F: 텍스트 생성
// ==================================================

type IDToChar map[string]string

func LoadVocab(filename string) (map[string]int, IDToChar, error) {
	data, err := os.ReadFile(filename)
	if err != nil {
		return nil, nil, err
	}

	var vocab struct {
		CharToID map[string]int `json:"char_to_id"`
		IDToChar IDToChar       `json:"id_to_char"`
	}

	if err := json.Unmarshal(data, &vocab); err != nil {
		return nil, nil, err
	}

	return vocab.CharToID, vocab.IDToChar, nil
}

// 간단한 생성기 (Greedy + Temperature sampling)
type Generator struct {
	charToID   map[string]int
	idToChar   IDToChar
	vocabSize  int
	tempScale  float64
}

func NewGenerator(charToID map[string]int, idToChar IDToChar, tempScale float64) *Generator {
	return &Generator{
		charToID:  charToID,
		idToChar:  idToChar,
		vocabSize: len(charToID),
		tempScale: tempScale,
	}
}

