package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"sync"
	"time"
)

// ==================================================
// FreeLang GPT - 서버 내 지속 학습 시스템
// ==================================================

// TrainingRequest 학습 요청
type TrainingRequest struct {
	Epochs       int     `json:"epochs"`
	LearningRate float64 `json:"learning_rate"`
	BatchSize    int     `json:"batch_size"`
	ValidateEvery int    `json:"validate_every"`
}

// TrainingResponse 학습 응답
type TrainingResponse struct {
	Status   string  `json:"status"`
	Message  string  `json:"message"`
	Started  bool    `json:"started"`
	TrainingID string `json:"training_id"`
}

// TrainingStatus 학습 상태
type TrainingStatus struct {
	TrainingID   string    `json:"training_id"`
	Status       string    `json:"status"`        // "idle", "running", "paused", "completed"
	Epoch        int       `json:"epoch"`
	TotalEpochs  int       `json:"total_epochs"`
	Step         int64     `json:"step"`
	Loss         float64   `json:"loss"`
	ValLoss      float64   `json:"val_loss"`
	LearningRate float64   `json:"learning_rate"`
	Progress     float64   `json:"progress"`      // 0.0 ~ 1.0
	ETA          string    `json:"eta"`
	StartTime    time.Time `json:"start_time"`
	LastUpdate   time.Time `json:"last_update"`
	ErrorMessage string    `json:"error_message"`
}

// TrainingServer 학습 서버
type TrainingServer struct {
	mu              sync.RWMutex
	status          TrainingStatus
	isTraining      bool
	trainingChannel chan bool
	trainer         interface{} // 실제 Trainer 타입
}

var (
	trainingServer *TrainingServer
)

// InitTrainingServer 학습 서버 초기화
func InitTrainingServer() {
	trainingServer = &TrainingServer{
		status: TrainingStatus{
			TrainingID: "training-001",
			Status:     "idle",
			Progress:   0.0,
		},
		isTraining:      false,
		trainingChannel: make(chan bool, 1),
	}
}

// ==================================================
// 학습 엔드포인트 핸들러
// ==================================================

// handleTrainStart 학습 시작
func handleTrainStart(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req TrainingRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, fmt.Sprintf("Invalid request: %v", err), http.StatusBadRequest)
		return
	}

	// 기본값 설정
	if req.Epochs == 0 {
		req.Epochs = 5
	}
	if req.LearningRate == 0 {
		req.LearningRate = 0.001
	}
	if req.BatchSize == 0 {
		req.BatchSize = 32
	}
	if req.ValidateEvery == 0 {
		req.ValidateEvery = 1
	}

	trainingServer.mu.Lock()
	defer trainingServer.mu.Unlock()

	if trainingServer.isTraining {
		http.Error(w, "Training already in progress", http.StatusConflict)
		return
	}

	// 학습 시작
	trainingServer.isTraining = true
	trainingServer.status.Status = "running"
	trainingServer.status.StartTime = time.Now()
	trainingServer.status.LastUpdate = time.Now()
	trainingServer.status.Epoch = 0
	trainingServer.status.TotalEpochs = req.Epochs
	trainingServer.status.LearningRate = req.LearningRate
	trainingServer.status.ErrorMessage = ""

	// 백그라운드에서 학습 실행
	go trainingServer.runTraining(req)

	response := TrainingResponse{
		Status:     "success",
		Message:    fmt.Sprintf("Training started with %d epochs", req.Epochs),
		Started:    true,
		TrainingID: trainingServer.status.TrainingID,
	}

	json.NewEncoder(w).Encode(response)
}

// handleTrainStatus 학습 상태 조회
func handleTrainStatus(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	trainingServer.mu.RLock()
	status := trainingServer.status
	trainingServer.mu.RUnlock()

	json.NewEncoder(w).Encode(status)
}

// handleTrainPause 학습 일시 중지
func handleTrainPause(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	trainingServer.mu.Lock()
	defer trainingServer.mu.Unlock()

	if !trainingServer.isTraining {
		http.Error(w, "No training in progress", http.StatusBadRequest)
		return
	}

	trainingServer.status.Status = "paused"
	trainingServer.status.LastUpdate = time.Now()

	response := map[string]interface{}{
		"status":  "success",
		"message": "Training paused",
		"epoch":   trainingServer.status.Epoch,
		"step":    trainingServer.status.Step,
	}

	json.NewEncoder(w).Encode(response)
}

// handleTrainResume 학습 재개
func handleTrainResume(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	trainingServer.mu.Lock()
	defer trainingServer.mu.Unlock()

	if trainingServer.status.Status != "paused" {
		http.Error(w, "Training not paused", http.StatusBadRequest)
		return
	}

	trainingServer.status.Status = "running"
	trainingServer.status.LastUpdate = time.Now()

	response := map[string]interface{}{
		"status":  "success",
		"message": "Training resumed",
	}

	json.NewEncoder(w).Encode(response)
}

// handleTrainStop 학습 중지
func handleTrainStop(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	trainingServer.mu.Lock()
	defer trainingServer.mu.Unlock()

	if !trainingServer.isTraining {
		http.Error(w, "No training in progress", http.StatusBadRequest)
		return
	}

	trainingServer.isTraining = false
	trainingServer.status.Status = "completed"
	trainingServer.status.LastUpdate = time.Now()

	response := map[string]interface{}{
		"status":  "success",
		"message": "Training stopped",
		"epoch":   trainingServer.status.Epoch,
		"step":    trainingServer.status.Step,
	}

	json.NewEncoder(w).Encode(response)
}

// handleTrainMetrics 학습 메트릭
func handleTrainMetrics(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	trainingServer.mu.RLock()
	defer trainingServer.mu.RUnlock()

	metrics := map[string]interface{}{
		"epoch":         trainingServer.status.Epoch,
		"total_epochs":  trainingServer.status.TotalEpochs,
		"step":          trainingServer.status.Step,
		"loss":          trainingServer.status.Loss,
		"val_loss":      trainingServer.status.ValLoss,
		"learning_rate": trainingServer.status.LearningRate,
		"progress":      trainingServer.status.Progress,
		"status":        trainingServer.status.Status,
	}

	json.NewEncoder(w).Encode(metrics)
}

// ==================================================
// 내부 학습 로직
// ==================================================

// runTraining 실제 학습 실행
func (ts *TrainingServer) runTraining(req TrainingRequest) {
	defer func() {
		ts.mu.Lock()
		ts.isTraining = false
		ts.status.Status = "completed"
		ts.status.LastUpdate = time.Now()
		ts.mu.Unlock()
	}()

	fmt.Printf("\n╔════════════════════════════════════════════════════════╗\n")
	fmt.Printf("║  FreeLang GPT - Server-side Training Started          ║\n")
	fmt.Printf("║  Continuous Learning System                           ║\n")
	fmt.Printf("╚════════════════════════════════════════════════════════╝\n\n")

	fmt.Printf("[CONFIG]\n")
	fmt.Printf("  Epochs:       %d\n", req.Epochs)
	fmt.Printf("  LearningRate: %.6f\n", req.LearningRate)
	fmt.Printf("  BatchSize:    %d\n", req.BatchSize)
	fmt.Printf("  ValidateEvery:%d\n\n", req.ValidateEvery)

	// 시뮬레이션: 에포크별 학습
	for epoch := 1; epoch <= req.Epochs; epoch++ {
		ts.mu.Lock()
		ts.status.Epoch = epoch
		ts.status.Progress = float64(epoch) / float64(req.Epochs)
		ts.status.Loss = 9.1746 - float64(epoch)*0.01 // 손실 감소 시뮬레이션
		ts.status.ValLoss = 8.8297 - float64(epoch)*0.01
		ts.status.LastUpdate = time.Now()
		ts.mu.Unlock()

		fmt.Printf("--- Epoch %d/%d ---\n", epoch, req.Epochs)
		fmt.Printf("  Train Loss: %.4f\n", ts.status.Loss)

		// 검증 (매 epoch마다)
		if epoch%req.ValidateEvery == 0 {
			fmt.Printf("  Val Loss:   %.4f\n", ts.status.ValLoss)
			if epoch < req.Epochs {
				fmt.Printf("  Progress:   %.1f%%\n", ts.status.Progress*100)
			}
		}

		// 학습 중단 신호 확인
		select {
		case <-ts.trainingChannel:
			fmt.Printf("\n⚠️ Training interrupted at epoch %d\n", epoch)
			return
		default:
		}

		// 에포크 간 대기 (시뮬레이션)
		time.Sleep(500 * time.Millisecond)
	}

	fmt.Printf("\n════════════════════════════════════════════════════════\n")
	fmt.Printf("📊 TRAINING COMPLETE\n")
	fmt.Printf("════════════════════════════════════════════════════════\n")
	fmt.Printf("Total Epochs:  %d\n", req.Epochs)
	fmt.Printf("Final Loss:    %.4f\n", ts.status.Loss)
	fmt.Printf("Final Val Loss:%.4f\n", ts.status.ValLoss)
	fmt.Printf("✅ Training finished successfully!\n")
}

// RegisterTrainingRoutes 학습 라우트 등록
func RegisterTrainingRoutes(mux *http.ServeMux) {
	InitTrainingServer()

	mux.HandleFunc("/train/start", handleTrainStart)
	mux.HandleFunc("/train/status", handleTrainStatus)
	mux.HandleFunc("/train/pause", handleTrainPause)
	mux.HandleFunc("/train/resume", handleTrainResume)
	mux.HandleFunc("/train/stop", handleTrainStop)
	mux.HandleFunc("/train/metrics", handleTrainMetrics)

	fmt.Println("✅ Training routes registered")
	fmt.Println("   POST   /train/start    - Start training")
	fmt.Println("   GET    /train/status   - Get training status")
	fmt.Println("   POST   /train/pause    - Pause training")
	fmt.Println("   POST   /train/resume   - Resume training")
	fmt.Println("   POST   /train/stop     - Stop training")
	fmt.Println("   GET    /train/metrics  - Get metrics")
}

