		<!-- 진행 바 -->
		<div class="card" style="margin-bottom: 30px;">
			<div class="metric-label">전체 진행 상황</div>
			<div class="progress-bar">
				<div class="progress-fill" id="progressFill" style="width: 0%;">
					<span id="progressText">0%</span>
				</div>
			</div>
			<div style="text-align: center; font-size: 12px; color: #999;">
				<span id="etaText">예상 남은 시간: -</span>
			</div>
		</div>

		<!-- 설정 패널 -->
		<div class="grid" style="grid-template-columns: 1fr 1fr; margin-bottom: 30px;">
			<div class="config-panel">
				<div class="config-group">
					<label>에포크 수</label>
					<input type="number" id="epochs" value="5" min="1" max="100">
				</div>
				<div class="config-group">
					<label>학습률</label>
					<input type="number" id="learningRate" value="0.001" min="0.00001" max="0.1" step="0.00001">
				</div>
				<div class="config-group">
					<label>배치 크기</label>
					<select id="batchSize">
						<option value="32">32</option>
						<option value="64">64</option>
						<option value="128">128</option>
					</select>
				</div>
			</div>

			<div class="info-box">
				<strong>💡 팁:</strong><br><br>
				• 에포크: 전체 데이터셋을 한 번 훈련하는 과정<br>
				• 학습률: 낮을수록 안정적, 높을수록 빠름<br>
				• 배치: 한 번에 처리하는 샘플 수<br><br>
				<strong>권장값:</strong> 5 에포크, 0.001 LR, 32 배치
			</div>
		</div>

		<!-- 차트 -->
		<div class="charts-grid">
			<div class="chart-container">
				<div class="chart-title">📈 손실 변화</div>
				<canvas id="lossChart"></canvas>
			</div>

			<div class="chart-container">
				<div class="chart-title">📊 검증 손실</div>
				<canvas id="valLossChart"></canvas>
			</div>
		</div>

		<!-- 로그 -->
		<div class="log-container">
			<div class="chart-title">📝 학습 로그</div>
			<div id="logContainer"></div>
		</div>

		<footer>
			<p>🚀 FreeLang GPT v1.0 | REST API 기반 지속 학습 시스템</p>
		</footer>
	</div>

	<script>
		let lossChart, valLossChart;
		let lossData = [];
		let valLossData = [];
		let epochData = [];
		let monitoringInterval;

		// 차트 초기화
		function initCharts() {
			// 손실 차트
			const lossCtx = document.getElementById('lossChart').getContext('2d');
			lossChart = new Chart(lossCtx, {
				type: 'line',
				data: {
					labels: epochData,
					datasets: [{
						label: '훈련 손실',
						data: lossData,
						borderColor: '#667eea',
						backgroundColor: 'rgba(102, 126, 234, 0.1)',
						tension: 0.4,
						fill: true,
						pointRadius: 4,
						pointHoverRadius: 6,
						pointBackgroundColor: '#667eea'
					}]
				},
				options: {
					responsive: true,
					maintainAspectRatio: true,
					plugins: {
						legend: { display: true }
					},
					scales: {
						y: { beginAtZero: false }
					}
				}
			});

			// 검증 손실 차트
			const valLossCtx = document.getElementById('valLossChart').getContext('2d');
			valLossChart = new Chart(valLossCtx, {
				type: 'line',
				data: {
					labels: epochData,
					datasets: [{
						label: '검증 손실',
						data: valLossData,
						borderColor: '#764ba2',
						backgroundColor: 'rgba(118, 75, 162, 0.1)',
						tension: 0.4,
						fill: true,
						pointRadius: 4,
						pointHoverRadius: 6,
						pointBackgroundColor: '#764ba2'
					}]
				},
				options: {
					responsive: true,
					maintainAspectRatio: true,
					plugins: {
						legend: { display: true }
					},
					scales: {
						y: { beginAtZero: false }
					}
				}
			});
		}

		// 상태 조회
		async function updateStatus() {
			try {
				const response = await fetch('/train/status');
				const data = await response.json();

				// UI 업데이트
				updateStatusBadge(data.status);
				document.getElementById('epoch').textContent = data.epoch;
				document.getElementById('epochTotal').textContent = '/ ' + data.total_epochs;
				document.getElementById('loss').textContent = data.loss.toFixed(4);
				document.getElementById('valLoss').textContent = data.val_loss.toFixed(4);
				document.getElementById('lr').textContent = data.learning_rate.toFixed(6);
				document.getElementById('progress').textContent = (data.progress * 100).toFixed(1) + '%';

				// 진행 바 업데이트
				const progressPercent = data.progress * 100;
				document.getElementById('progressFill').style.width = progressPercent + '%';
				document.getElementById('progressText').textContent = progressPercent.toFixed(1) + '%';

				// 차트 데이터 업데이트
				updateChartData(data.epoch, data.loss, data.val_loss);

				// 로그 추가
				addLog('상태 조회: Epoch ' + data.epoch + ', Loss: ' + data.loss.toFixed(4));

				// 학습 완료 시
				if (data.status === 'completed') {
					clearInterval(monitoringInterval);
					document.getElementById('pauseBtn').disabled = true;
					document.getElementById('resumeBtn').style.display = 'none';
					addLog('✅ 학습 완료!');
				}
			} catch (error) {
				addLog('❌ 오류: ' + error.message);
			}
		}

		// 상태 배지 업데이트
		function updateStatusBadge(status) {
			const badge = document.getElementById('status');
			badge.className = 'status-badge status-' + status;
			const labels = {
				'idle': 'Idle',
				'running': 'Running',
				'paused': 'Paused',
				'completed': 'Completed'
			};
			badge.textContent = labels[status] || status;

			// 버튼 활성화/비활성화
			const pauseBtn = document.getElementById('pauseBtn');
			const resumeBtn = document.getElementById('resumeBtn');

			if (status === 'running') {
				pauseBtn.style.display = 'inline-block';
				resumeBtn.style.display = 'none';
				pauseBtn.disabled = false;
			} else if (status === 'paused') {
				pauseBtn.style.display = 'none';
				resumeBtn.style.display = 'inline-block';
				resumeBtn.disabled = false;
			} else {
				pauseBtn.style.display = 'inline-block';
				resumeBtn.style.display = 'none';
				pauseBtn.disabled = true;
				resumeBtn.disabled = true;
			}
		}

		// 차트 데이터 업데이트
		function updateChartData(epoch, loss, valLoss) {
			if (!epochData.includes(epoch)) {
				epochData.push(epoch);
				lossData.push(loss);
				valLossData.push(valLoss);

				if (lossChart) {
					lossChart.data.labels = epochData;
					lossChart.data.datasets[0].data = lossData;
					lossChart.update();
				}

				if (valLossChart) {
					valLossChart.data.labels = epochData;
					valLossChart.data.datasets[0].data = valLossData;
					valLossChart.update();
				}
			}
		}

		// 로그 추가
		function addLog(message) {
			const logContainer = document.getElementById('logContainer');
			const entry = document.createElement('div');
			entry.className = 'log-entry';

			const time = new Date().toLocaleTimeString('ko-KR');
			entry.innerHTML = '<span class="log-timestamp">[' + time + ']</span> ' + message;

			logContainer.insertBefore(entry, logContainer.firstChild);

			// 최대 50개 로그만 유지
			while (logContainer.children.length > 50) {
				logContainer.removeChild(logContainer.lastChild);
			}
		}

		// 학습 시작
		async function startTraining() {
			const epochs = parseInt(document.getElementById('epochs').value);
			const learningRate = parseFloat(document.getElementById('learningRate').value);
			const batchSize = parseInt(document.getElementById('batchSize').value);

			try {
				const response = await fetch('/train/start', {
					method: 'POST',
					headers: { 'Content-Type': 'application/json' },
					body: JSON.stringify({
						epochs: epochs,
						learning_rate: learningRate,
						batch_size: batchSize,
						validate_every: 1
					})
				});

				const data = await response.json();
				addLog('✅ 학습 시작: ' + epochs + ' 에포크');

				// 모니터링 시작
				clearInterval(monitoringInterval);
				monitoringInterval = setInterval(updateStatus, 2000);

				updateStatus();
			} catch (error) {
				addLog('❌ 오류: ' + error.message);
			}
		}

		// 일시 중지
		async function pauseTraining() {
			try {
				await fetch('/train/pause', { method: 'POST' });
				addLog('⏸ 학습 일시 중지');
			} catch (error) {
				addLog('❌ 오류: ' + error.message);
			}
		}

		// 재개
		async function resumeTraining() {
			try {
				await fetch('/train/resume', { method: 'POST' });
				addLog('▶ 학습 재개');
				monitoringInterval = setInterval(updateStatus, 2000);
			} catch (error) {
				addLog('❌ 오류: ' + error.message);
			}
		}

		// 중지
		async function stopTraining() {
			try {
				clearInterval(monitoringInterval);
				await fetch('/train/stop', { method: 'POST' });
				addLog('⏹ 학습 중지');
				updateStatus();
			} catch (error) {
				addLog('❌ 오류: ' + error.message);
			}
		}

		// 새로고침
		function refreshStatus() {
			addLog('🔄 상태 새로고침');
			updateStatus();
		}

		// 초기화
		window.addEventListener('load', () => {
			initCharts();
			updateStatus();
			addLog('📊 대시보드 로드됨');
		});

		// 자동 업데이트
		setInterval(updateStatus, 5000);
	</script>
</body>
</html>
`

	fmt.Fprint(w, html)
}

// RegisterDashboardRoute 대시보드 라우트 등록
func RegisterDashboardRoute(mux *http.ServeMux) {
	mux.HandleFunc("/dashboard", handleDashboard)
	fmt.Println("✅ Dashboard route registered")
	fmt.Println("   GET    /dashboard  - Learning visualization")
}

