		"requests":   2450,
	}

	json.NewEncoder(w).Encode(response)
}

// handleExportMetrics 메트릭 내보내기
func handleExportMetrics(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/csv")
	w.Header().Set("Content-Disposition", "attachment; filename=metrics.csv")

	epochs, losses, valLosses, lrs := metricsHistory.GetHistory()

	// CSV 헤더
	fmt.Fprintf(w, "Epoch,Loss,ValLoss,LearningRate\n")

	// CSV 데이터
	for i := 0; i < len(epochs); i++ {
