// ==================================================

// MetricsHistory 메트릭 히스토리
type MetricsHistory struct {
	mu              sync.RWMutex
	Epochs          []int
	Losses          []float64
	ValLosses       []float64
	LearningRates   []float64
	Timestamps      []time.Time
	MaxSize         int
}

// TrainingAnalytics 학습 분석
type TrainingAnalytics struct {
	TotalEpochs     int
	BestLoss        float64
	BestValLoss     float64
	BestEpoch       int
	LossImprovement float64
	ConvergenceRate float64
	EstimatedTime   time.Duration
	AverageSpeed    float64
	GPUMemory       uint64
	CPUUsage        float64
}

// PerformanceReport 성능 보고서
type PerformanceReport struct {
	Status          string
	Timestamp       time.Time
	Metrics         TrainingAnalytics
	HistorySize     int
	IsOptimal       bool
	Recommendations []string
}

var metricsHistory = &MetricsHistory{
	Epochs:        make([]int, 0),
	Losses:        make([]float64, 0),
	ValLosses:     make([]float64, 0),
	LearningRates: make([]float64, 0),
	Timestamps:    make([]time.Time, 0),
	MaxSize:       1000,
}

// RecordMetric 메트릭 기록
func (m *MetricsHistory) RecordMetric(epoch int, loss, valLoss, lr float64) {
	m.mu.Lock()
	defer m.mu.Unlock()

	m.Epochs = append(m.Epochs, epoch)
	m.Losses = append(m.Losses, loss)
	m.ValLosses = append(m.ValLosses, valLoss)
	m.LearningRates = append(m.LearningRates, lr)
	m.Timestamps = append(m.Timestamps, time.Now())

	// 크기 제한
	if len(m.Epochs) > m.MaxSize {
		m.Epochs = m.Epochs[1:]
		m.Losses = m.Losses[1:]
		m.ValLosses = m.ValLosses[1:]
		m.LearningRates = m.LearningRates[1:]
		m.Timestamps = m.Timestamps[1:]
	}
}

// GetHistory 히스토리 조회
func (m *MetricsHistory) GetHistory() ([]int, []float64, []float64, []float64) {
	m.mu.RLock()
	defer m.mu.RUnlock()

	epochs := make([]int, len(m.Epochs))
	losses := make([]float64, len(m.Losses))
	valLosses := make([]float64, len(m.ValLosses))
	lrs := make([]float64, len(m.LearningRates))

	copy(epochs, m.Epochs)
	copy(losses, m.Losses)
	copy(valLosses, m.ValLosses)
	copy(lrs, m.LearningRates)

	return epochs, losses, valLosses, lrs
}

// Clear 히스토리 초기화
func (m *MetricsHistory) Clear() {
	m.mu.Lock()
	defer m.mu.Unlock()

	m.Epochs = make([]int, 0)
	m.Losses = make([]float64, 0)
	m.ValLosses = make([]float64, 0)
	m.LearningRates = make([]float64, 0)
	m.Timestamps = make([]time.Time, 0)
}

// ==================================================
// 모니터링 핸들러
// ==================================================

// handleMetricsHistory 메트릭 히스토리 조회
func handleMetricsHistory(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	epochs, losses, valLosses, lrs := metricsHistory.GetHistory()

	response := map[string]interface{}{
		"epochs":           epochs,
		"losses":           losses,
		"val_losses":       valLosses,
		"learning_rates":   lrs,
		"history_size":     len(epochs),
		"max_history_size": metricsHistory.MaxSize,
	}

	json.NewEncoder(w).Encode(response)
}

// handleAnalytics 학습 분석
func handleAnalytics(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	epochs, losses, valLosses, _ := metricsHistory.GetHistory()

	analytics := TrainingAnalytics{
		TotalEpochs: len(epochs),
	}

	if len(losses) > 0 {
		// 최고 손실
		minLoss := losses[0]
		minIdx := 0
		for i, l := range losses {
			if l < minLoss {
				minLoss = l
				minIdx = i
			}
		}
		analytics.BestLoss = minLoss
		analytics.BestEpoch = minIdx

		// 최고 검증 손실
		minValLoss := valLosses[0]
		for _, l := range valLosses {
			if l < minValLoss {
				minValLoss = l
			}
		}
		analytics.BestValLoss = minValLoss

		// 손실 개선도
		if len(losses) > 1 {
			analytics.LossImprovement = ((losses[0] - losses[len(losses)-1]) / losses[0]) * 100
		}

		// 수렴 속도 (초기 5개 에포크와 마지막 5개 에포크 비교)
		if len(losses) >= 10 {
			initialAvg := (losses[0] + losses[1] + losses[2] + losses[3] + losses[4]) / 5
			finalAvg := (losses[len(losses)-5] + losses[len(losses)-4] + losses[len(losses)-3] + losses[len(losses)-2] + losses[len(losses)-1]) / 5
			analytics.ConvergenceRate = ((initialAvg - finalAvg) / initialAvg) * 100
		}

		// 평균 속도
		if len(epochs) > 1 && len(metricsHistory.Timestamps) > 1 {
			startTime := metricsHistory.Timestamps[0]
			endTime := metricsHistory.Timestamps[len(metricsHistory.Timestamps)-1]
			elapsed := endTime.Sub(startTime).Seconds()
			if elapsed > 0 {
				analytics.AverageSpeed = float64(len(epochs)) / elapsed
			}
		}
	}

	response := map[string]interface{}{
		"total_epochs":     analytics.TotalEpochs,
		"best_loss":        analytics.BestLoss,
		"best_val_loss":    analytics.BestValLoss,
