		"loss_improvement": fmt.Sprintf("%.2f%%", analytics.LossImprovement),
		"convergence_rate": fmt.Sprintf("%.2f%%", analytics.ConvergenceRate),
		"average_speed":    fmt.Sprintf("%.2f epochs/sec", analytics.AverageSpeed),
	}

	json.NewEncoder(w).Encode(response)
}

