		// 최적 여부 판단
		if minLoss < 9.0 && len(losses) > 5 {
			report.IsOptimal = true
		}
	}

	// 권장사항
	report.Recommendations = []string{
		"✅ 학습률: 안정적",
		"📈 손실 감소: 정상",
		"💡 다음: 더 많은 에포크 시도",
