package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
)

// ==================================================
// Phase G: REST API 서버
// ==================================================

// API 요청/응답 구조
type GenerateRequest struct {
	Prompt      string  `json:"prompt"`
	MaxTokens   int     `json:"max_tokens"`
	Temperature float64 `json:"temperature"`
	Model       string  `json:"model"` // "simple" or "advanced"
}

type GenerateResponse struct {
	Prompt     string `json:"prompt"`
	Generated  string `json:"generated"`
	FullText   string `json:"full_text"`
	Model      string `json:"model"`
	Tokens     int    `json:"tokens"`
	Time       string `json:"time_ms"`
}

type HealthResponse struct {
	Status  string `json:"status"`
	Model   string `json:"model"`
	Vocab   int    `json:"vocab_size"`
	Ready   bool   `json:"ready"`
}

type ModelInfo struct {
	Name       string `json:"name"`
	VocabSize  int    `json:"vocab_size"`
	EmbedDim   int    `json:"embed_dim"`
	MaxLayers  int    `json:"max_layers"`
	Parameters int    `json:"parameters"`
}

// ==================================================
// 전역 상태
// ==================================================

var (
	charToID map[string]int
	idToChar map[string]string
	models   map[string]*ModelInfo
)

// ==================================================
// HTTP 핸들러
// ==================================================

// 건강 상태 확인
func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	response := HealthResponse{
		Status:  "ok",
		Model:   "FreeLang GPT",
		Vocab:   len(charToID),
		Ready:   true,
	}

	json.NewEncoder(w).Encode(response)
}

// 모델 정보
func handleModelInfo(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	modelList := []ModelInfo{
		{
			Name:       "Simple Linear",
			VocabSize:  11267,
			EmbedDim:   128,
			MaxLayers:  1,
			Parameters: 1400000,
		},
		{
			Name:       "Advanced Multi-Layer",
			VocabSize:  11267,
			EmbedDim:   128,
			MaxLayers:  4,
			Parameters: 2500000,
		},
	}

	w.Header().Set("X-Models-Count", fmt.Sprintf("%d", len(modelList)))
	json.NewEncoder(w).Encode(map[string]interface{}{
		"models": modelList,
		"default": "Simple Linear",
	})
}

// 텍스트 생성 (Main handler)
func handleGenerate(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	// CORS 헤더
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("Access-Control-Allow-Methods", "POST, OPTIONS")
	w.Header().Set("Access-Control-Allow-Headers", "Content-Type")

	// OPTIONS 요청 처리
	if r.Method == http.MethodOptions {
		w.WriteHeader(http.StatusOK)
		return
	}

	if r.Method != http.MethodPost {
		w.WriteHeader(http.StatusMethodNotAllowed)
		json.NewEncoder(w).Encode(map[string]string{
			"error": "Only POST method allowed",
		})
		return
	}

	// 요청 파싱
	var req GenerateRequest
	body, err := io.ReadAll(r.Body)
	if err != nil {
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(map[string]string{"error": "Failed to read body"})
		return
	}
	defer r.Body.Close()

	if err := json.Unmarshal(body, &req); err != nil {
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(map[string]string{"error": "Invalid JSON"})
		return
	}

	// 검증
	if req.Prompt == "" {
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(map[string]string{"error": "Prompt is required"})
		return
	}

	if req.MaxTokens == 0 {
		req.MaxTokens = 50 // 기본값
	}

	if req.Temperature == 0 {
		req.Temperature = 0.7 // 기본값
	}

	if req.Model == "" {
		req.Model = "simple" // 기본 모델
	}

	// 텍스트 생성 로직 (간단한 버전)
	generated := generateText(req.Prompt, req.MaxTokens, req.Temperature, req.Model)

	// 응답
	response := GenerateResponse{
		Prompt:    req.Prompt,
		Generated: generated,
		FullText:  req.Prompt + generated,
		Model:     req.Model,
		Tokens:    len(strings.Fields(generated)),
		Time:      "0ms",
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(response)
}

// 토크나이저 (Encode)
func handleEncode(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodPost {
		w.WriteHeader(http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		Text string `json:"text"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(map[string]string{"error": "Invalid JSON"})
		return
	}

	// 인코딩 (간단한 버전)
	var ids []int
	for _, ch := range req.Text {
		key := fmt.Sprintf("%d", ch)
		if id, ok := charToID[key]; ok {
			ids = append(ids, id)
		}
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]interface{}{
		"text":   req.Text,
		"tokens": ids,
		"count":  len(ids),
	})
}

// 토크나이저 (Decode)
func handleDecode(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodPost {
		w.WriteHeader(http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		Tokens []int `json:"tokens"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(map[string]string{"error": "Invalid JSON"})
		return
	}

	// 디코딩 (간단한 버전)
	var text string
	for _, id := range req.Tokens {
		key := fmt.Sprintf("%d", id)
		if ch, ok := idToChar[key]; ok {
			text += ch
		}
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]interface{}{
		"tokens": req.Tokens,
		"text":   text,
	})
}

// 통계
func handleStats(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	stats := map[string]interface{}{
		"vocab_size": len(charToID),
		"models": []map[string]interface{}{
			{
				"name":       "simple",
				"parameters": 1400000,
				"layers":     1,
			},
			{
				"name":       "advanced",
				"parameters": 2500000,
				"layers":     4,
			},
		},
		"data": map[string]interface{}{
			"corpus_size":  "14.5MB",
			"tokens":       "9.8M",
			"sequences":    "8.8M",
			"train_split":  "90%",
			"val_split":    "10%",
		},
	}

	json.NewEncoder(w).Encode(stats)
}

// ==================================================
// 텍스트 생성 (더미 구현)
// ==================================================

func generateText(prompt string, maxTokens int, temperature float64, model string) string {
	// 실제 구현: 모델 로드 및 생성
	// 현재: 간단한 더미 출력

	var result strings.Builder

