package main

import (
	"fmt"
	"net/http"
)

// 경로 매칭 함수
func matchPath(pattern string, path string) bool {
	if len(pattern) > len(path) {
		return false
	}
	if pattern == "/" {
		return true
	}
	if path[:len(pattern)] == pattern {
		if len(path) == len(pattern) || path[len(pattern)] == '/' || path[len(pattern)] == '?' {
			return true
		}
	}
	return false
}

func main() {
	tests := []struct {
		pattern string
		path    string
		want    bool
	}{
		{"/metrics/analytics", "/metrics/analytics", true},
		{"/metrics/", "/metrics/analytics", true},
		{"/", "/metrics/analytics", true},
		{"/health", "/health", true},
		{"/api/", "/api/generate", true},
	}

	for _, tt := range tests {
		got := matchPath(tt.pattern, tt.path)
		fmt.Printf("matchPath(%q, %q) = %v, want %v\n", tt.pattern, tt.path, got, tt.want)
	}
}
EOF
